/* ---------- Withdrawal request (Travel · Vendor · Affiliate) ---------- */
A['wd-req'] = el => { const ws = el.dataset.ws; const x = me(ws); const bal = ws === 'affiliate' ? COMMISSIONS.filter(c => c.aff === x.id && c.state === 'approved').reduce((s, c) => s + c.amount, 0) : x.balance; modal({ title: L3(['Ajukan withdrawal', 'Request withdrawal', 'طلب سحب']), body: `<p class="muted" style="margin-top:0">${L3(['Saldo tersedia', 'Available', 'متاح'])}: <b class="tnum">${money(bal, true)}</b></p>` + fields([{ k: 'amount', label: 'Jumlah (Rp)', type: 'number', req: true, min: 100000, step: 100000, def: ws === 'affiliate' ? bal : Math.min(bal, 50000000) }], 'wr-') + `<div class="auditbox">${ic('shieldc')}<span>${L3(['Rekening tujuan terverifikasi •••• ' + (x.id.charCodeAt(4) * 37 % 9000 + 1000) + '. Withdrawal di atas Rp 50 jt butuh approval Finance.', 'Verified payout account •••• ' + (x.id.charCodeAt(4) * 37 % 9000 + 1000) + '. Withdrawals above Rp 50M need Finance approval.', 'حساب موثق.'])}</span></div>`, foot: `<button class="btn" data-act="close">${t('cancel')}</button><button class="btn primary" data-act="wd-go" data-ws="${ws}" data-bal="${bal}">${L3(['Ajukan', 'Submit', 'إرسال'])}</button>` }); };
A['wd-go'] = el => { const ws = el.dataset.ws; const x = me(ws); const v = formVals([{ k: 'amount', type: 'number', req: true }], 'wr-'); if (!v) return; if (v.amount > +el.dataset.bal || v.amount <= 0) { const f = document.getElementById('wr-amount'); f.style.borderColor = 'var(--bad)'; toast('bad', L3(['Melebihi saldo tersedia', 'Exceeds available balance', 'يتجاوز الرصيد']), money(+el.dataset.bal, true)); return; }
  const pt = { travel: 'Travel', vendor: 'Vendor', affiliate: 'Affiliate' }[ws]; const w = { id: uid('WD'), party: x.name, partyType: pt, ref: x.id, amount: v.amount, state: 'pending', basis: ws === 'vendor' ? 'Order selesai' : ws === 'travel' ? 'Saldo settlement' : 'Komisi tervalidasi', ts: nowTs() }; WITHDRAWALS.unshift(w);
  if (ws === 'affiliate') { let left = v.amount; COMMISSIONS.filter(c => c.aff === x.id && c.state === 'approved').forEach(c => { if (left > 0) { c.state = 'paid'; left -= c.amount; } }); x.payable = Math.max(0, (x.payable || 0) - v.amount); } else x.balance -= v.amount;
  const a = pApproval({ type: 'withdrawal', domain: 'Keuangan', title: 'Withdrawal ' + x.name, requester: x.name, reqRef: x.id, reqRoute: '/finance/withdrawal', amount: v.amount, priority: v.amount > 50e6 ? 'p1' : 'p2', risk: v.amount > 200e6 ? 45 : 18, ctx: [['Nominal', v.amount], ['Pihak', pt], ['Basis', w.basis]], source: 'Portal ' + pt });
  pAudit(ws, 'withdrawal.request', 'Withdrawal/' + w.id, { after: String(v.amount) }); pNotif('approval', 'info', L3(['Withdrawal baru', 'New withdrawal', 'سحب جديد']), x.name + ' · ' + money(v.amount), '/approval/' + a.id); closeOverlays(); toast('ok', L3(['Withdrawal diajukan', 'Withdrawal requested', 'طُلب السحب']), money(v.amount, true) + ' → Finance'); rerender(); };

