function createBooking(pkgId, travelerId, pax, source, extra) { const p = pkgById(pkgId); if (p.seats - p.sold < pax) { toast('bad', L3(['Seat tidak cukup', 'Not enough seats', 'مقاعد غير كافية']), (p.seats - p.sold) + ' ' + L3(['tersisa', 'left', 'متبقية'])); return null; } const tr = travelById(p.travel); const b = Object.assign({ id: uid('BK'), traveler: travelerId, pkg: p.id, travel: p.travel, pax, total: p.price * pax, paid: 0, state: 'awaiting_payment', created: nowTs(), dep: p.dep, payMode: tr.payMode, source }, extra || {}); if (!b.agen) delete b.agen; BOOKINGS.unshift(b); p.sold += pax; const prov = PROVIDERS.find(x => x.status === 'healthy') || PROVIDERS[0]; PAYMENTS.unshift({ id: uid('PAY'), booking: b.id, travel: b.travel, payer: travelerId, amount: Math.round(b.total * .3 / 1000) * 1000, provider: prov.name, channel: 'VA BSI', ref: prov.id.slice(0, 3).toUpperCase() + '-' + Date.now().toString(36).toUpperCase(), status: 'pending', ts: nowTs(), recon: 'pending', flow: b.payMode, fee: 4000 }); pNotif('booking', 'info', L3(['Booking baru', 'New booking', 'حجز جديد']), b.id + ' · ' + trvName(travelerId) + ' · ' + source, '/booking/' + b.id); return b; }

